.c-button-demo {
  --button-accent: #b9f474;
  --button-accent-text: #162600;
  --button-border: #dcddd4;
  --button-border-strong: #bfc1b7;
  --button-canvas: #f5f5ef;
  --button-control-height: 2.75rem;
  --button-focus: #b9f474;
  --button-font: Inter, ui-sans-serif, system-ui, sans-serif;
  --button-muted: #62665d;
  --button-radius: 0.55rem;
  --button-surface: #ffffff;
  --button-text: #171915;

  align-content: center;
  background: var(--button-canvas);
  color: var(--button-text);
  display: grid;
  font-family: var(--button-font);
  gap: 1rem;
  min-height: 100%;
  padding: 2rem;
}

.c-button-demo__row {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.c-button {
  align-items: center;
  background: var(--button-surface);
  border: 1px solid var(--button-border-strong);
  border-radius: var(--button-radius);
  color: var(--button-text);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-weight: 650;
  gap: 0.5rem;
  justify-content: center;
  min-height: var(--button-control-height);
  padding: 0.75rem 1rem;
  text-decoration: none;
}

.c-button:hover:not(:disabled) {
  border-color: var(--button-text);
}

.c-button:focus-visible {
  outline: 0.2rem solid var(--button-focus);
  outline-offset: 0.15rem;
}

.c-button:active:not(:disabled) {
  box-shadow: inset 0 0 0 1px var(--button-text);
}

.c-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.c-button--primary {
  background: var(--button-accent);
  border-color: var(--button-accent);
  color: var(--button-accent-text);
}

.c-button--quiet {
  background: transparent;
  border-color: transparent;
}

.c-button svg {
  block-size: 1.1rem;
  inline-size: 1.1rem;
  stroke: currentColor;
}

.c-button-demo__status {
  color: var(--button-muted);
  line-height: 1.6;
  margin: 0;
}

@media (prefers-reduced-motion: reduce) {
  .c-button {
    scroll-behavior: auto;
  }
}

