export interface ButtonController {
  destroy(): void;
}

export function createButton(root: Element): ButtonController {
  const status = root.querySelector<HTMLElement>('[data-button-status]');

  if (!status) {
    throw new Error('Button demo markup is incomplete.');
  }

  const handleClick = (event: Event): void => {
    const target = event.target;
    if (!(target instanceof Element)) return;

    const button = target.closest<HTMLButtonElement>('[data-button-action]');
    if (!button || !root.contains(button)) return;

    const action = button.dataset['buttonAction'] || button.textContent?.trim() || 'Button';
    status.textContent = `${action} activated.`;
    root.dispatchEvent(new CustomEvent('button:activate', {
      detail: { action }
    }));
  };

  root.addEventListener('click', handleClick);

  return {
    destroy(): void {
      root.removeEventListener('click', handleClick);
    }
  };
}

document.querySelectorAll<HTMLElement>('[data-component="button"]').forEach(createButton);

