export function createBusyButton(root) {
  const button = root.querySelector('[data-busy-button]');
  const label = root.querySelector('[data-button-label]');
  const status = root.querySelector('[data-button-status]');

  if (!(button instanceof HTMLButtonElement) || !(label instanceof HTMLElement) || !(status instanceof HTMLElement)) {
    throw new Error('Busy button markup is incomplete.');
  }

  let timer = 0;

  const setBusy = (busy) => {
    button.disabled = busy;
    button.setAttribute('aria-busy', String(busy));
    label.textContent = busy ? 'Saving…' : 'Save changes';
    status.textContent = busy ? 'Saving changes.' : 'Changes saved.';
  };

  const handleClick = () => {
    setBusy(true);
    timer = window.setTimeout(() => setBusy(false), 1200);
  };

  button.addEventListener('click', handleClick);

  return {
    setBusy,
    destroy() {
      window.clearTimeout(timer);
      button.removeEventListener('click', handleClick);
    }
  };
}

document.querySelectorAll('[data-component="busy-button"]').forEach(createBusyButton);

